from __future__ import annotations; from datetime import UTC, date, datetime, timedelta; from decimal import Decimal; from uuid import UUID; import pytest; from src.pricing.base.errors import NoObservationError; from src.pricing.base.observation import Authority, ObservationSource, PriceObservation; from src.pricing.base.policy import ResolutionPolicy; from src.pricing.base.subject import PriceableSubject; SUBJECT = PriceableSubject.security('AAPL'); OTHER_SUBJECT = PriceableSubject.security('MSFT')
def _observation(*, value: str, as_of: date, observed_at: datetime, source: ObservationSource=ObservationSource.CRAWLER, authority: Authority=Authority.CRAWLER, subject: PriceableSubject=SUBJECT, id: UUID | None=None) -> PriceObservation:
    if observed_at.tzinfo is None: observed_at = observed_at.replace(tzinfo=UTC)
    kwargs = {'id': id} if id is not None else {}; return PriceObservation(subject=subject, value=Decimal(value), as_of=as_of, observed_at=observed_at, source=source, authority=authority, currency='USD', **kwargs)
def test_picks_the_only_eligible_candidate():
    from src.pricing.extension.resolve import resolve; candidate = _observation(value='100', as_of=date(2026, 6, 1), observed_at=datetime(2026, 6, 1, 12)); result = resolve(SUBJECT, date(2026, 6, 1), ResolutionPolicy(), [candidate]); assert result is candidate; from src.pricing.extension.resolve import resolve; _m1_other = _observation(value='200', as_of=date(2026, 6, 1), observed_at=datetime(2026, 6, 1, 12), subject=OTHER_SUBJECT)
    with pytest.raises(NoObservationError): resolve(SUBJECT, date(2026, 6, 1), ResolutionPolicy(), [_m1_other])
    from src.pricing.extension.resolve import resolve; _m2_future = _observation(value='100', as_of=date(2026, 6, 15), observed_at=datetime(2026, 6, 15, 12))
    with pytest.raises(NoObservationError): resolve(SUBJECT, date(2026, 6, 1), ResolutionPolicy(), [_m2_future])
    from src.pricing.extension.resolve import resolve; _m3_crawler_only = _observation(value='100', as_of=date(2026, 6, 1), observed_at=datetime(2026, 6, 1, 12), source=ObservationSource.CRAWLER, authority=Authority.CRAWLER); _m3_policy = ResolutionPolicy(min_authority=Authority.MANUAL)
    with pytest.raises(NoObservationError): resolve(SUBJECT, date(2026, 6, 1), _m3_policy, [_m3_crawler_only])
    from src.pricing.extension.resolve import resolve; _m4_manual = _observation(value='105', as_of=date(2026, 6, 1), observed_at=datetime(2026, 6, 1, 12), source=ObservationSource.MANUAL, authority=Authority.MANUAL); _m4_policy = ResolutionPolicy(min_authority=Authority.MANUAL); _m4_result = resolve(SUBJECT, date(2026, 6, 1), _m4_policy, [_m4_manual]); assert _m4_result is _m4_manual; from src.pricing.extension.resolve import resolve; _m5_stale = _observation(value='90', as_of=date(2026, 1, 1), observed_at=datetime(2026, 1, 1, 12)); _m5_policy = ResolutionPolicy(max_age_days=30)
    with pytest.raises(NoObservationError): resolve(SUBJECT, date(2026, 6, 1), _m5_policy, [_m5_stale])
    from src.pricing.extension.resolve import resolve; _m6_as_of = date(2026, 6, 1); _m6_within_window = _observation(value='90', as_of=_m6_as_of - timedelta(days=10), observed_at=datetime(2026, 5, 22, 12)); _m6_policy = ResolutionPolicy(max_age_days=30); _m6_result = resolve(SUBJECT, _m6_as_of, _m6_policy, [_m6_within_window]); assert _m6_result is _m6_within_window; from src.pricing.extension.resolve import resolve; _m7_crawler_latest = _observation(value='100', as_of=date(2026, 6, 1), observed_at=datetime(2026, 6, 1, 9), source=ObservationSource.CRAWLER, authority=Authority.CRAWLER); _m7_override_older = _observation(value='999', as_of=date(2026, 5, 1), observed_at=datetime(2026, 5, 1, 9), source=ObservationSource.OVERRIDE, authority=Authority.OVERRIDE); _m7_result = resolve(SUBJECT, date(2026, 6, 1), ResolutionPolicy(), [_m7_crawler_latest, _m7_override_older]); assert _m7_result is _m7_override_older; from src.pricing.extension.resolve import resolve; _m8_earlier = _observation(value='100', as_of=date(2026, 5, 1), observed_at=datetime(2026, 5, 1, 9)); _m8_later = _observation(value='110', as_of=date(2026, 6, 1), observed_at=datetime(2026, 5, 2, 9)); _m8_result = resolve(SUBJECT, date(2026, 6, 1), ResolutionPolicy(), [_m8_earlier, _m8_later]); assert _m8_result is _m8_later; from src.pricing.extension.resolve import resolve; _m9_original = _observation(value='100', as_of=date(2026, 6, 1), observed_at=datetime(2026, 6, 1, 9)); _m9_backfilled_correction = _observation(value='103', as_of=date(2026, 6, 1), observed_at=datetime(2026, 6, 10, 9)); _m9_result = resolve(SUBJECT, date(2026, 6, 1), ResolutionPolicy(), [_m9_original, _m9_backfilled_correction]); assert _m9_result is _m9_backfilled_correction; from src.pricing.extension.resolve import resolve
    with pytest.raises(NoObservationError): resolve(SUBJECT, date(2026, 6, 1), ResolutionPolicy(), [])
    from src.pricing.extension.resolve import resolve; _m11_same_moment = datetime(2026, 6, 1, 9, tzinfo=UTC); _m11_lower_id = _observation(value='100', as_of=date(2026, 6, 1), observed_at=_m11_same_moment, id=UUID(int=1)); _m11_higher_id = _observation(value='101', as_of=date(2026, 6, 1), observed_at=_m11_same_moment, id=UUID(int=2)); assert resolve(SUBJECT, date(2026, 6, 1), ResolutionPolicy(), [_m11_lower_id, _m11_higher_id]) is _m11_higher_id; assert resolve(SUBJECT, date(2026, 6, 1), ResolutionPolicy(), [_m11_higher_id, _m11_lower_id]) is _m11_higher_id
@pytest.mark.parametrize('policy', [ResolutionPolicy(), ResolutionPolicy(max_age_days=4), ResolutionPolicy(min_authority=Authority.STATEMENT), ResolutionPolicy(max_age_days=2, min_authority=Authority.MANUAL)])
def test_AC_pricing_fx_4_resolve_series_equals_one_resolve_per_date(policy: ResolutionPolicy):
    'AC-pricing.fx.4'; import random; from src.pricing.extension.resolve import resolve, resolve_series; rng = random.Random(2583); start = date(2026, 6, 1); candidates = [_observation(value=str(rng.randint(90, 110)), as_of=start + timedelta(days=rng.randint(0, 40)), observed_at=datetime(2026, 5, 1, tzinfo=UTC) + timedelta(hours=rng.randint(0, 3)), authority=rng.choice(list(Authority)), subject=rng.choice([SUBJECT, SUBJECT, OTHER_SUBJECT]), id=UUID(int=index + 1)) for index in range(300)]; dates = [start + timedelta(days=offset) for offset in range(-3, 46)]; series = resolve_series(SUBJECT, dates, policy, candidates); expected = {}
    for as_of in dates:
        try: expected[as_of] = resolve(SUBJECT, as_of, policy, candidates)
        except NoObservationError: continue
    assert series == expected; assert dates[0] not in series; assert len(series) > 30
